import{_ as t}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as r,D as o,o as n,c as d,I as c,w as b,k as l,a as h,R as u,b as m,e as E}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const O=JSON.parse('{"title":"发布订阅与 Stream 消费组","description":"区分实时通知与可回读日志，通过 pending、确认、接管和幂等管理消息生命周期。","frontmatter":{"title":"发布订阅与 Stream 消费组","date":"2026-10-06T00:00:00.000Z","category":"Java课程","tags":["Java","Redis","可靠性"],"description":"区分实时通知与可回读日志，通过 pending、确认、接管和幂等管理消息生命周期。"},"headers":[],"relativePath":"courses/java/15-Redis/10-发布订阅与Stream消费组.md","filePath":"courses/java/15-Redis/10-发布订阅与Stream消费组.md","lastUpdated":1791253598000}'),g={name:"courses/java/15-Redis/10-发布订阅与Stream消费组.md"},v=l("h1",{id:"发布订阅与-stream-消费组",tabindex:"-1"},[h("发布订阅与 Stream 消费组 "),l("a",{class:"header-anchor",href:"#发布订阅与-stream-消费组","aria-label":'Permalink to "发布订阅与 Stream 消费组"'},"​")],-1),k=u(`<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>区分实时通知与可回读日志，通过 pending、确认、接管和幂等管理消息生命周期。</p><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>本篇采用 Redis 8 稳定主版本的基础语义；官方文档核对日期：2026-10-06，不声明未验证的补丁版本。需要更高小版本的选项单独标明。</p><p>Pub/Sub 无离线恢复；Streams 消费组维护游标和 PEL，为重新投递提供状态，实际可靠性仍取决于持久化、保留策略与业务提交。Stream 不保证端到端 exactly-once；命令响应丢失和消费者崩溃都需要恢复设计。</p><p>实验只在本机独立可丢弃 Redis 8、数据库 0 中执行。先通过终端运行 <code>redis-cli -h 127.0.0.1 -p 6379</code>，在交互提示符输入 redis 代码块；有 ACL 时使用 <code>--user lab_user --askpass</code>，不在命令中写密码。输出数组的排版因客户端而异。每节独立重建输入，命名空间 <code>lab:{reliability}:</code> 专用于学习；开始和结束只清理本节明确列出的 key，不把通配符传给删除命令。运行前确认没有业务数据，配置与恢复步骤另按注明的受控前提执行。</p><h2 id="常用用法" tabindex="-1">常用用法 <a class="header-anchor" href="#常用用法" aria-label="Permalink to &quot;常用用法&quot;">​</a></h2><h3 id="subscribe-pub-sub-在线订阅与断连丢失" tabindex="-1"><code>SUBSCRIBE</code>：Pub/Sub 在线订阅与断连丢失 <a class="header-anchor" href="#subscribe-pub-sub-在线订阅与断连丢失" aria-label="Permalink to &quot;\`SUBSCRIBE\`：Pub/Sub 在线订阅与断连丢失&quot;">​</a></h3><p>用于在专用连接上接收一个实验频道的实时消息。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：打开连接 A，仅供订阅，暂无其他订阅者。</span></span>
<span class="line"><span>SUBSCRIBE lab:reliability:news</span></span>
<span class="line"><span># 关键变化：连接 A 进入订阅状态，随后由下一节的连接 B 发布。</span></span>
<span class="line"><span># 输出：subscribe、频道名、订阅数 1；发布时收到 message、频道名、hello。</span></span></code></pre></div><p>Pub/Sub 是 at-most-once：离线、断连或处理失败的消息不会重放，没有 ACK/PEL。RESP2 订阅态只允许有限命令，应使用专用连接；不要把订阅连接送回普通连接池。适合允许丢失的通知；关键事件改用有持久化与业务恢复协议的日志/队列。<a href="https://redis.io/docs/latest/commands/subscribe/" target="_blank" rel="noreferrer">SUBSCRIBE</a>、<a href="https://redis.io/docs/latest/develop/pubsub/" target="_blank" rel="noreferrer">Pub/Sub 投递语义</a>。</p><h3 id="publish-订阅者数量不代表业务处理成功" tabindex="-1"><code>PUBLISH</code>：订阅者数量不代表业务处理成功 <a class="header-anchor" href="#publish-订阅者数量不代表业务处理成功" aria-label="Permalink to &quot;\`PUBLISH\`：订阅者数量不代表业务处理成功&quot;">​</a></h3><p>用于从第二个连接发布消息并观察服务端匹配的订阅数。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：连接 A 已按上一节订阅，连接 B 是普通本机连接。</span></span>
<span class="line"><span>PUBLISH lab:reliability:news hello</span></span>
<span class="line"><span># 关键变化：hello 被投递给当前在线订阅连接，无日志条目保留。</span></span>
<span class="line"><span># 输出：独立单节点且仅 A 订阅时整数 1，A 收到 hello。</span></span></code></pre></div><p>断开 A 后再发布通常返回 0，重新连接不能获取这条旧消息；返回 1 也不说明应用已经处理。PUBLISH O(N+M)，随订阅者和匹配模式增加。频道不按 SELECT 数据库隔离；使用业务命名空间。Cluster 广播与分片 Pub/Sub 的路由/计数语义要按拓扑核对，不把单节点计数当全网处理确认。<a href="https://redis.io/docs/latest/commands/publish/" target="_blank" rel="noreferrer">PUBLISH</a>。</p><h3 id="xgroup-create-从起点建立消费组" tabindex="-1"><code>XGROUP CREATE</code>：从起点建立消费组 <a class="header-anchor" href="#xgroup-create-从起点建立消费组" aria-label="Permalink to &quot;\`XGROUP CREATE\`：从起点建立消费组&quot;">​</a></h3><p>用于创建独立 Stream 的组状态以消费全部历史记录。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 危险：只清理该可丢弃学习 Stream，连同组状态会被删除。</span></span>
<span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span># 初始：实验 Stream 和消费组均不存在。</span></span>
<span class="line"><span># 关键变化：创建日志条目与 groups.workers 游标 0，尚无 PEL。</span></span>
<span class="line"><span># 输出：清理数、&quot;1-0&quot;、OK。</span></span></code></pre></div><p>0 从已有日志最早条目开始，$ 跳过建组时已有记录，仅后续新条目可由 &gt; 读取；MKSTREAM 可创建空日志。组已存在时报 BUSYGROUP，不随意删除生产组重建。XGROUP CREATE O(1)。组间独立，同组消费者竞争分配；不是每个消费者都拿每条新消息。<a href="https://redis.io/docs/latest/commands/xgroup-create/" target="_blank" rel="noreferrer">XGROUP CREATE</a>。</p><h3 id="xreadgroup-新消息、pel-与重启读取" tabindex="-1"><code>XREADGROUP</code>：新消息、PEL 与重启读取 <a class="header-anchor" href="#xreadgroup-新消息、pel-与重启读取" aria-label="Permalink to &quot;\`XREADGROUP\`：新消息、PEL 与重启读取&quot;">​</a></h3><p>用于观察送达后未确认的事件仍在消费组待处理列表中。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events &gt;</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events 0</span></span>
<span class="line"><span># 初始：只含 1-0 的学习 Stream，新建 workers 与 c1。</span></span>
<span class="line"><span># 关键变化：第一次分配 1-0 到 c1 的 PEL，第二次重读 c1 自己的 pending。</span></span>
<span class="line"><span># 输出：清理数、&quot;1-0&quot;、OK；两次读取均包含 1-0/event_id/order-1。</span></span></code></pre></div><p>危险：DEL 仅用于明确的可丢弃学习 Stream，不能用于重置生产消费组。&gt; 读取未分配过的新记录；0 等具体 ID 查询该消费者自身 pending，不接管别的消费者。BLOCK 毫秒等待新消息，0 无限等待当前连接；设置有界超时与 COUNT。NOACK 不维护 PEL，不能用于需要恢复的处理。成本取决于返回条数，阻塞消费者多时 XADD 还承担唤醒成本；Cluster 多 Stream 需同槽。PEL 只代表送达未确认，不保证业务已提交，也不是自动重试定时器。<a href="https://redis.io/docs/latest/commands/xreadgroup/" target="_blank" rel="noreferrer">XREADGROUP</a>。</p><h3 id="xack-业务完成后确认与日志保留" tabindex="-1"><code>XACK</code>：业务完成后确认与日志保留 <a class="header-anchor" href="#xack-业务完成后确认与日志保留" aria-label="Permalink to &quot;\`XACK\`：业务完成后确认与日志保留&quot;">​</a></h3><p>用于确认已处理的消息并观察重复确认不会重复移除。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events &gt;</span></span>
<span class="line"><span>XACK lab:{reliability}:events workers 1-0</span></span>
<span class="line"><span>XACK lab:{reliability}:events workers 1-0</span></span>
<span class="line"><span>XLEN lab:{reliability}:events</span></span>
<span class="line"><span># 初始：建立单条学习日志，业务处理已成功持久提交后才确认。</span></span>
<span class="line"><span># 关键变化：1-0 从 workers 的 PEL 移除，但日志载荷仍在。</span></span>
<span class="line"><span># 输出：清理数、ID、OK、事件；1、0、1。</span></span></code></pre></div><p>危险：初始化 DEL 仅针对可丢弃学习 key。XACK O(ID 数)，只清除指定组的 pending，不删除日志，也不替其他组确认。先 ACK 后处理可能永久漏处理；先处理后 ACK 在断连时会重复，必须业务幂等。确认超时可重试，返回 0 可能已确认或不存在，需结合业务处理记录判断。<a href="https://redis.io/docs/latest/commands/xack/" target="_blank" rel="noreferrer">XACK</a>。</p><h3 id="xpending-观察积压、空闲和重试次数" tabindex="-1"><code>XPENDING</code>：观察积压、空闲和重试次数 <a class="header-anchor" href="#xpending-观察积压、空闲和重试次数" aria-label="Permalink to &quot;\`XPENDING\`：观察积压、空闲和重试次数&quot;">​</a></h3><p>用于查看一个已送达未确认条目的所有者与空闲时间。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events &gt;</span></span>
<span class="line"><span>XPENDING lab:{reliability}:events workers</span></span>
<span class="line"><span>XPENDING lab:{reliability}:events workers - + 10</span></span>
<span class="line"><span># 初始：workers 只有一个分配给 c1 的未确认事件。</span></span>
<span class="line"><span># 关键变化：读取组的总积压和该条目的投递元数据。（lab 学习数据）。</span></span>
<span class="line"><span># 输出：摘要总数 1，最小/最大 ID 为 1-0；明细含 1-0、c1、动态空闲毫秒、投递次数 1。</span></span></code></pre></div><p>危险：初始化只删除独立学习 Stream。摘要与明细成本不同；按 COUNT 有界读取，带 IDLE 过滤时扫描成本也需评估。监控 pending 数、最老年龄、消费者闲置和投递次数；次数不等于数据库事务尝试次数。XPENDING 只观测不重发，毒消息需退避、最大尝试次数和受控死信转移（包含原 ID、原因、次数）；持久记录死信后再 ACK，跨系统边界仍需幂等。<a href="https://redis.io/docs/latest/commands/xpending/" target="_blank" rel="noreferrer">XPENDING</a>。</p><h3 id="xautoclaim-接管闲置消息与有界重试" tabindex="-1"><code>XAUTOCLAIM</code>：接管闲置消息与有界重试 <a class="header-anchor" href="#xautoclaim-接管闲置消息与有界重试" aria-label="Permalink to &quot;\`XAUTOCLAIM\`：接管闲置消息与有界重试&quot;">​</a></h3><p>用于把超出最小空闲时间的 pending 转移给恢复消费者。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events &gt;</span></span>
<span class="line"><span># 初始：c1 已拿到 1-0，但未 ACK；本机演示 min-idle=0，无需等待。</span></span>
<span class="line"><span>XAUTOCLAIM lab:{reliability}:events workers c2 0 0-0 COUNT 1</span></span>
<span class="line"><span># 关键变化：1-0 所有者变为 c2，空闲时间重置，常规接管增加投递计数。</span></span>
<span class="line"><span># 输出：下一游标、含 1-0 的事件数组、被清理的已删除 ID 数组（本例为空）。</span></span></code></pre></div><p>危险：DEL 只清理学习 Stream，min-idle=0 仅用于本机演示，生产不得立即抢占活跃任务。自 6.2 提供；Redis 7+ 返回第三数组，扫描遇到载荷已删除的记录会清除 PEL 并报告 ID。按返回游标循环至 0-0，空批次也可能需继续；单次扫描最多 COUNT×10 个候选，可少于 COUNT。生产阈值高于正常处理耗时并包含停顿余量，仍可能与旧消费者并行；接管不能提供 exactly-once。JUSTID 不增加重试计数，需另记录尝试策略。<a href="https://redis.io/docs/latest/commands/xautoclaim/" target="_blank" rel="noreferrer">XAUTOCLAIM</a>。</p><h3 id="set-nx-消费幂等与业务事务边界" tabindex="-1"><code>SET NX</code>：消费幂等与业务事务边界 <a class="header-anchor" href="#set-nx-消费幂等与业务事务边界" aria-label="Permalink to &quot;\`SET NX\`：消费幂等与业务事务边界&quot;">​</a></h3><p>用于演示同一个事件 ID 重复出现时可检测重复。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:dedup-order-1</span></span>
<span class="line"><span>SET lab:{reliability}:dedup-order-1 processed NX EX 3600</span></span>
<span class="line"><span>SET lab:{reliability}:dedup-order-1 processed NX EX 3600</span></span>
<span class="line"><span># 初始：学习 key 模拟同一个 event_id=order-1 的去重记录。</span></span>
<span class="line"><span># 关键变化：order-1 首次占位成功，重复占位失败。</span></span>
<span class="line"><span># 输出：清理数、OK、nil；只验证 Redis 标记，未执行任何业务事务。</span></span></code></pre></div><p>这个标记不能直接实现可靠消费：先占位再业务，崩溃会漏处理；先业务再占位，崩溃会重复。可靠方案是在权威数据库的同一个事务中插入 event_id 唯一约束与业务变更，提交后 XACK；重复事件查已提交结果再确认。跨外部系统副作用使用幂等键/outbox，不能跨 Redis 和数据库凭空获得事务。去重保留期覆盖日志重放、pending 恢复与最大延迟；TTL 结束后重新投递可能再执行。<a href="https://redis.io/docs/latest/commands/set/" target="_blank" rel="noreferrer">SET NX</a>。这是对存储提交边界的应用层推导。</p><h3 id="xtrim-keepref-裁剪载荷与保留-pel-的区别" tabindex="-1"><code>XTRIM KEEPREF</code>：裁剪载荷与保留 PEL 的区别 <a class="header-anchor" href="#xtrim-keepref-裁剪载荷与保留-pel-的区别" aria-label="Permalink to &quot;\`XTRIM KEEPREF\`：裁剪载荷与保留 PEL 的区别&quot;">​</a></h3><p>用于在 Redis 8.2+ 的可丢弃实例观察裁剪后仍有 pending 引用。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 危险：只在可丢弃 Stream 上裁剪；载荷删除不可由 PEL 恢复。</span></span>
<span class="line"><span># 边界：DEL 仅用于明确的可丢弃 lab 学习键范围，禁止生产批量误删。</span></span>
<span class="line"><span>DEL lab:{reliability}:events</span></span>
<span class="line"><span>XADD lab:{reliability}:events 1-0 event_id order-1</span></span>
<span class="line"><span>XGROUP CREATE lab:{reliability}:events workers 0</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events &gt;</span></span>
<span class="line"><span>XTRIM lab:{reliability}:events MAXLEN = 0 KEEPREF</span></span>
<span class="line"><span>XPENDING lab:{reliability}:events workers</span></span>
<span class="line"><span>XREADGROUP GROUP workers c1 COUNT 1 STREAMS lab:{reliability}:events 0</span></span>
<span class="line"><span># 初始：1-0 在 c1 的 PEL，载荷仍存在，服务支持 Redis 8.2+ 选项。</span></span>
<span class="line"><span># 关键变化：日志条目被删除，PEL 仍保留 1-0 引用。</span></span>
<span class="line"><span># 输出：清理数、ID、OK、事件、1；pending 总数仍为 1，重读得到 1-0 但载荷为 null。</span></span></code></pre></div><p>本节是消费组裁剪引用的规范位置；基础 MAXLEN/= 与 ~ 示例仍见 <a href="./05-Bitmap-HyperLogLog-GEO与Stream#xtrim-按精确最大条数修剪实验日志并观察残留事件">特殊结构的 XTRIM</a>，不重复其命令教程。显式 KEEPREF/DELREF/ACKED 自 Redis 8.2 提供：KEEPREF 为默认行为，仅留引用，不能恢复载荷；DELREF 同时清除所有组对应 PEL 引用，可能丢失待处理任务；ACKED 只裁剪已被所有组读取且确认的条目，因此不能保证达到 MAXLEN。早期版本使用无选项裁剪也会留下 pending 引用，本例的显式参数不可在 8.0 使用。修剪 O(删除数量)，~ 可能多保留，LIMIT 限制扫描工作且只与近似模式使用。保留窗口应覆盖最慢消费者、最大故障与重放需求；监控组 lag、pending 年龄与载荷缺失，不能只看 XLEN。三种策略都不能替代备份与可靠消息处理。<a href="https://redis.io/docs/latest/commands/xtrim/" target="_blank" rel="noreferrer">XTRIM 引用策略</a>。</p><h2 id="易混点" tabindex="-1">易混点 <a class="header-anchor" href="#易混点" aria-label="Permalink to &quot;易混点&quot;">​</a></h2><p>XACK 移除待确认引用而不删除日志；XTRIM 可能删除日志却保留引用；PEL 存在不代表载荷完整。</p><h2 id="课后小问" tabindex="-1">课后小问 <a class="header-anchor" href="#课后小问" aria-label="Permalink to &quot;课后小问&quot;">​</a></h2><ol><li>消费者业务已提交，但 XACK 前退出应怎样恢复？</li></ol><p>答案：重投后按同一 event_id 验证已提交记录并跳过重复副作用，再确认，业务事务和去重必须协调。</p><ol start="2"><li>怎样处理写命令响应丢失？</li></ol><p>答案：响应丢失不能证明没有执行；先检查业务状态，对非幂等写入使用业务 ID、去重记录或有界恢复流程。</p><h2 id="本节小结" tabindex="-1">本节小结 <a class="header-anchor" href="#本节小结" aria-label="Permalink to &quot;本节小结&quot;">​</a></h2><p>选择可接受丢失的通知或有恢复状态的日志，再把业务幂等、持久化和保留窗口组合成可靠流程。</p><h2 id="快速回顾" tabindex="-1">快速回顾 <a class="header-anchor" href="#快速回顾" aria-label="Permalink to &quot;快速回顾&quot;">​</a></h2><p>按 H3 定位真实命令或操作流程，重建初始状态并读回结果，再检查超时、容量和数据安全边界。</p>`,54);function P(a,R,C,A,S,y){const p=t,i=o("ClientOnly");return n(),d("div",null,[v,c(i,null,{default:b(()=>{var s,e;return[(((s=a.$frontmatter)==null?void 0:s.aside)??!0)&&(((e=a.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(n(),m(p,{key:0,article:a.$frontmatter},null,8,["article"])):E("",!0)]}),_:1}),k])}const L=r(g,[["render",P]]);export{O as __pageData,L as default};
